//! Web font containers: raw sfnt, WOFF 1.0 and WOFF 2.0, and hostile input.
//!
//! The `Px*` fonts are generated by `examples/fixture_fonts.rs`; their `.woff` and
//! `.woff2` siblings were made from the `.ttf` by the reference tooling (see
//! `tests/fonts/PROVENANCE`), so decoding them checks this crate against an
//! independent encoder.

use px_text::font::Font;
use px_text::sfnt::FontError;
use px_text::woff::{self, Container};

const ICONS_TTF: &[u8] = include_bytes!("../../../tests/fonts/PxIcons-Regular.ttf");
const ICONS_WOFF: &[u8] = include_bytes!("../../../tests/fonts/PxIcons-Regular.woff");
const ICONS_WOFF2: &[u8] = include_bytes!("../../../tests/fonts/PxIcons-Regular.woff2");
const TEXT_TTF: &[u8] = include_bytes!("../../../tests/fonts/PxText-Regular.ttf");
const TEXT_WOFF2: &[u8] = include_bytes!("../../../tests/fonts/PxText-Regular.woff2");
const BOLD_TTF: &[u8] = include_bytes!("../../../tests/fonts/PxText-Bold.ttf");
const BOLD_WOFF2: &[u8] = include_bytes!("../../../tests/fonts/PxText-Bold.woff2");

/// Every observable the renderer uses: glyph ids, advances, outlines.
fn fingerprint(f: &Font, chars: &[char]) -> Vec<(u16, u16, usize)> {
    chars
        .iter()
        .map(|&c| {
            let g = f.glyph_index(c).unwrap_or(0);
            (
                g,
                f.advance(g).unwrap_or(0),
                f.outline(g).map(|o| o.commands.len()).unwrap_or(usize::MAX),
            )
        })
        .collect()
}

#[test]
fn containers_are_recognised() {
    assert_eq!(woff::sniff(ICONS_TTF), Some(Container::Sfnt));
    assert_eq!(woff::sniff(ICONS_WOFF), Some(Container::Woff));
    assert_eq!(woff::sniff(ICONS_WOFF2), Some(Container::Woff2));
    assert_eq!(woff::sniff(b"<html>"), None);
    assert_eq!(woff::sniff(b""), None);
}

#[test]
fn woff1_and_woff2_decode_to_the_same_font_as_the_ttf() {
    let icons: Vec<char> = ('\u{E000}'..='\u{E004}').collect();
    let want = fingerprint(&woff::load_font(ICONS_TTF).unwrap(), &icons);
    assert!(want.iter().all(|w| w.0 != 0), "icons are mapped");
    assert_eq!(
        fingerprint(&woff::load_font(ICONS_WOFF).unwrap(), &icons),
        want
    );
    assert_eq!(
        fingerprint(&woff::load_font(ICONS_WOFF2).unwrap(), &icons),
        want
    );

    let text: Vec<char> = "AZaz09 ".chars().collect();
    for (ttf, w2) in [(TEXT_TTF, TEXT_WOFF2), (BOLD_TTF, BOLD_WOFF2)] {
        assert_eq!(
            fingerprint(&woff::load_font(w2).unwrap(), &text),
            fingerprint(&woff::load_font(ttf).unwrap(), &text)
        );
    }
}

#[test]
fn woff2_glyf_transform_reproduces_the_outlines_exactly() {
    // The glyph data is re-encoded by the decoder, so compare the geometry.
    let a = woff::load_font(ICONS_TTF).unwrap();
    let b = woff::load_font(ICONS_WOFF2).unwrap();
    for g in 0..a.num_glyphs() {
        let (oa, ob) = (a.outline(g).unwrap(), b.outline(g).unwrap());
        assert_eq!(oa.commands, ob.commands, "glyph {g}");
    }
}

#[test]
fn every_truncation_and_bit_flip_returns_instead_of_panicking() {
    for file in [ICONS_WOFF, ICONS_WOFF2, TEXT_WOFF2] {
        for n in 0..file.len() {
            let _ = woff::load_font(&file[..n]);
        }
        for i in 0..file.len() * 8 {
            let mut m = file.to_vec();
            m[i / 8] ^= 1 << (i % 8);
            let _ = woff::load_font(&m);
        }
    }
}

#[test]
fn pseudo_random_garbage_with_valid_signatures_never_panics() {
    let mut x: u32 = 0x1234_5678;
    let mut next = move || {
        x = x.wrapping_mul(1_664_525).wrapping_add(1_013_904_223);
        (x >> 24) as u8
    };
    for sig in [&b"wOFF"[..], b"wOF2", &[0, 1, 0, 0]] {
        for _ in 0..200 {
            let mut buf = sig.to_vec();
            buf.extend((0..200).map(|_| next()));
            let _ = woff::load_font(&buf);
        }
    }
}

fn be32(v: &mut [u8], at: usize, x: u32) {
    v[at..at + 4].copy_from_slice(&x.to_be_bytes());
}

#[test]
fn woff1_size_lies_are_refused_before_anything_is_allocated() {
    // Declared total sfnt size beyond the cap.
    let mut f = ICONS_WOFF.to_vec();
    be32(&mut f, 16, u32::MAX);
    assert!(woff::to_sfnt(&f).is_err());
    // A table whose declared original length is huge: the inflater is capped at
    // that length, and the sum is capped by the declared sfnt size.
    let mut f = ICONS_WOFF.to_vec();
    be32(&mut f, 44 + 12, 0x7fff_ffff);
    assert!(woff::to_sfnt(&f).is_err());
    // compressed larger than original.
    let mut f = ICONS_WOFF.to_vec();
    be32(&mut f, 44 + 8, 0x1000_0000);
    assert!(woff::to_sfnt(&f).is_err());
    // length field not the file length.
    let mut f = ICONS_WOFF.to_vec();
    be32(&mut f, 8, 1);
    assert!(woff::to_sfnt(&f).is_err());
    // A table offset past the end of the file.
    let mut f = ICONS_WOFF.to_vec();
    be32(&mut f, 44 + 4, 0xffff_fff0);
    assert!(woff::to_sfnt(&f).is_err());
}

#[test]
fn woff2_size_lies_are_refused() {
    // totalSfntSize over the cap.
    let mut f = ICONS_WOFF2.to_vec();
    be32(&mut f, 16, u32::MAX);
    assert!(woff::to_sfnt(&f).is_err());
    // totalCompressedSize larger than the file.
    let mut f = ICONS_WOFF2.to_vec();
    be32(&mut f, 20, 0x7fff_ffff);
    assert!(woff::to_sfnt(&f).is_err());
    // A directory entry claiming a gigantic table: UIntBase128 5 bytes of 0xff..
    let mut f = ICONS_WOFF2.to_vec();
    // First table entry: flags byte at 48; then origLength.
    f.splice(49..50, [0xff, 0xff, 0xff, 0xff, 0x7f]);
    assert!(woff::to_sfnt(&f).is_err());
}

#[test]
fn a_zlib_bomb_in_a_woff_table_stops_at_the_declared_size() {
    // One table (`cmap`, never inspected) of 64 MiB of zeros, deflated with
    // stored/fixed blocks is large; instead use a tiny dynamic stream that expands
    // far beyond the declared original length and check the cap holds.
    // zlib stream of 1 MiB zeros (compressed ~1 KiB) built from stored blocks is
    // not small, so reuse a real expansion: fixed-Huffman "match length 258 at
    // distance 1" repeated.
    let mut z = vec![0x78, 0x01];
    // BFINAL=1, BTYPE=01 (fixed). Literal 0, then 4000 matches of length 258, dist 1.
    let mut bits: Vec<bool> = vec![true, true, false];
    let push = |bits: &mut Vec<bool>, v: u32, n: u32, msb_first: bool| {
        for i in 0..n {
            let b = if msb_first {
                (v >> (n - 1 - i)) & 1
            } else {
                (v >> i) & 1
            };
            bits.push(b == 1);
        }
    };
    push(&mut bits, 0x30, 8, true); // literal 0
    for _ in 0..4000 {
        push(&mut bits, 0xc5, 8, true); // length symbol 285 = 258
        push(&mut bits, 0, 5, true); // distance code 0 = 1
    }
    push(&mut bits, 0, 7, true); // end of block
    let mut cur = 0u8;
    for (i, b) in bits.iter().enumerate() {
        if *b {
            cur |= 1 << (i % 8);
        }
        if i % 8 == 7 {
            z.push(cur);
            cur = 0;
        }
    }
    if !bits.len().is_multiple_of(8) {
        z.push(cur);
    }
    z.extend_from_slice(&[0, 0, 0, 0]); // Adler-32 (never reached)
    let declared = 8000usize;
    // Build a WOFF with a single table that claims `declared` original bytes.
    let mut f = Vec::new();
    f.extend_from_slice(b"wOFF");
    f.extend_from_slice(&[0, 1, 0, 0]);
    f.extend_from_slice(&[0; 4]); // length, patched
    f.extend_from_slice(&1u16.to_be_bytes());
    f.extend_from_slice(&[0; 2]);
    f.extend_from_slice(&(declared as u32 + 12 + 16).to_be_bytes());
    f.extend_from_slice(&[0; 24]);
    f.extend_from_slice(b"cmap");
    let offset = 44 + 20;
    f.extend_from_slice(&(offset as u32).to_be_bytes());
    f.extend_from_slice(&(z.len() as u32).to_be_bytes());
    f.extend_from_slice(&(declared as u32).to_be_bytes());
    f.extend_from_slice(&[0; 4]);
    f.extend_from_slice(&z);
    let len = f.len() as u32;
    be32(&mut f, 8, len);
    assert!(z.len() < declared, "the stream is smaller than it claims");
    assert!(woff::to_sfnt(&f).is_err());
}

#[test]
fn unsupported_flavours_are_named_not_misread() {
    // A `ttcf` header on a file that is not a collection is a bad collection.
    let mut ttc = ICONS_TTF.to_vec();
    ttc[..4].copy_from_slice(b"ttcf");
    assert!(woff::load_font(&ttc).is_err());
    assert!(woff::load_font(b"not a font at all").is_err());
    // WOFF 2.0 collections are named, not misread.
    let mut f = ICONS_WOFF2.to_vec();
    f[4..8].copy_from_slice(b"ttcf");
    assert_eq!(
        woff::load_font(&f).unwrap_err(),
        FontError::Unsupported("WOFF2 font collection")
    );
}

#[test]
fn files_over_the_cap_are_refused_unread() {
    let big = vec![0u8; woff::MAX_FILE_BYTES + 1];
    assert!(woff::to_sfnt(&big).is_err());
}
